  `PurchasedIncludesLab` TINYINT(1) NOT NULL,
  `PurchasedIncludesPharmacy` TINYINT(1) NOT NULL,
  `PaymentMethod` VARCHAR(30) NOT NULL,
  `PaymentStatus` VARCHAR(30) NOT NULL,
  `GatewayOrderId` VARCHAR(150) NULL,
  `GatewayPaymentId` VARCHAR(150) NULL,
  `AdminCreationStatus` VARCHAR(30) NOT NULL,
  `AdminUserId` INT NULL,
  `HospitalId` INT NULL,
  `CreatedAt` DATETIME(6) NOT NULL,
  `PaidAt` DATETIME(6) NULL,
  `ActivatedAt` DATETIME(6) NULL,
  `LastPaymentAttemptAt` DATETIME(6) NULL,
  `PaymentAttemptCount` INT NOT NULL,
  `PaymentFailureReason` VARCHAR(500) NULL,
  `TransactionReference` VARCHAR(150) NULL,
  `PurchaseType` VARCHAR(20) NOT NULL,
