  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `SubscriptionRequests` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `Name` VARCHAR(150) NOT NULL,
  `Email` VARCHAR(256) NOT NULL,
  `MobileNumber` VARCHAR(10) NOT NULL,
  `SubscriptionPlanId` INT NOT NULL,
  `PlanName` VARCHAR(150) NOT NULL,
  `Amount` DECIMAL(18, 2) NOT NULL,
  `DurationMonths` INT NOT NULL,
  `IncludesLab` TINYINT(1) NOT NULL,
  `Status` VARCHAR(30) NOT NULL,
  `CreatedAt` DATETIME(6) NOT NULL,
  `PaidAt` DATETIME(6) NULL,
  `UpdatedAt` DATETIME(6) NULL,
  `AdminUserId` INT NULL,
  `HospitalId` INT NULL,
  `IncludesCms` TINYINT(1) NOT NULL,
  `IncludesPharmacy` TINYINT(1) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `SuperAdmins` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `Name` LONGTEXT NULL,
  `Email` VARCHAR(450) NULL,
  `PasswordHash` LONGTEXT NULL,
  `IsActive` TINYINT(1) NOT NULL,
  `CreatedAt` DATETIME(6) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `UserPermissions` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `UserId` INT NOT NULL,
  `HospitalId` INT NOT NULL,
  `Module` VARCHAR(450) NOT NULL,
  `CanView` TINYINT(1) NOT NULL,
  `CanCreate` TINYINT(1) NOT NULL,
  `CanEdit` TINYINT(1) NOT NULL,
  `CanDelete` TINYINT(1) NOT NULL,
  `AssignedByUserId` INT NOT NULL,
  `UpdatedAt` DATETIME(6) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `Users` (
  `Id` INT NOT NULL AUTO_INCREMENT,
  `Name` LONGTEXT NULL,
  `MobileNumber` LONGTEXT NULL,
  `Email` LONGTEXT NULL,
  `PasswordHash` LONGTEXT NULL,
  `Role` LONGTEXT NULL,
  `DoctorId` INT NULL,
  `HospitalId` INT NULL,
  `BranchId` INT NULL,
  `IsActive` TINYINT(1) NOT NULL,
  `CreatedAt` DATETIME(6) NOT NULL,
  `MustChangePassword` TINYINT(1) NOT NULL,
  `EmailVerified` TINYINT(1) NOT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

